import{bQ as r,aZ as o,aL as n,u as s,G as e,I as p}from"./chunks/framework.C1gZXFVa.js";const f=JSON.parse('{"title":"强平与清算","description":"标记价更新后撮合扫描风险，触发系统强平单并完成减仓或平仓清算；与用户主动平仓分流。","frontmatter":{"title":"强平与清算","description":"标记价更新后撮合扫描风险，触发系统强平单并完成减仓或平仓清算；与用户主动平仓分流。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/080503"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/080503"}],["meta",{"property":"og:title","content":"强平与清算 · TGEX"}],["meta",{"property":"og:description","content":"标记价更新后撮合扫描风险，触发系统强平单并完成减仓或平仓清算；与用户主动平仓分流。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"强平与清算 · TGEX"}],["meta",{"name":"twitter:description","content":"标记价更新后撮合扫描风险，触发系统强平单并完成减仓或平仓清算；与用户主动平仓分流。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"强平与清算\\",\\"description\\":\\"标记价更新后撮合扫描风险，触发系统强平单并完成减仓或平仓清算；与用户主动平仓分流。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/080503\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/080503\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/080503.md","filePath":"08.合约手册/05.核心流程/03.强平与清算.md"}'),i={name:"pages/080503.md"};function d(l,t,h,g,c,_){const a=o("Flow");return n(),s("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">合约手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="强平与清算" tabindex="-1">强平与清算 <a class="header-anchor" href="#强平与清算" aria-label="Permalink to &quot;强平与清算&quot;">​</a></h1><div class="doc-lead">强平不是用户点的平仓按钮，而是风险旁路：行情刷新标记价 → 撮合扫描 → 命中后限制操作并提交系统强平单 → 改持仓与账户 → 留下清算明细。</div><p>价格口径见<a href="/pages/0803#fees">交易规则 · 价格</a>；对象边界见<a href="/pages/0804#risk">核心设计 · 风险</a>。</p><h2 id="_1-标记价进入撮合" tabindex="-1">1. 标记价进入撮合 <a class="header-anchor" href="#_1-标记价进入撮合" aria-label="Permalink to &quot;1. 标记价进入撮合&quot;">​</a></h2><p>合约行情维护指数 / 标记等价格，经消息推给撮合。撮合更新本地价格缓存后，对相关用户 / 仓位做风险扫描。</p><p><strong>过期或异常价格不应继续当实时标记价用</strong>；行情侧应对时间戳、跳变与源中断有降级或暂停策略，见<a href="/pages/080504">行情推送流程</a>。</p><h2 id="_2-触发条件-语义" tabindex="-1">2. 触发条件（语义） <a class="header-anchor" href="#_2-触发条件-语义" aria-label="Permalink to &quot;2. 触发条件（语义）&quot;">​</a></h2><p>当权益相对维持保证金等要求不再满足时（具体公式与档位以产品为准），进入强平处理。不要写成「只要亏完开仓时那笔初始保证金就一定强平」——维持要求、浮盈浮亏口径、全仓共享都会改触发点。</p><h2 id="_3-执行阶段" tabindex="-1">3. 执行阶段 <a class="header-anchor" href="#_3-执行阶段" aria-label="Permalink to &quot;3. 执行阶段&quot;">​</a></h2><p>设计抽象（顺序以当前引擎为准）：</p>',11)),p(a,{steps:["命中风险条件","限制相关开平操作","处理冲突中的用户委托","提交强平减仓或平仓","确认持仓与账户结果","记录清算明细"]}),t[1]||(t[1]=e('<p>要点：</p><ol><li><strong>与用户平仓分流</strong>：系统单有独立来源标识；结果仍写同一套持仓 / 账户热缓存。</li><li><strong>可能全平或部分减仓</strong>：是否 <code>全部强平</code> 还是 <code>部分强平</code> 取决于引擎规则，文档不固化阈值。</li><li><strong>触发 ≠ 清算完成</strong>：扫描命中、强平单进簿、成交清算是不同阶段；中间行情与排队仍可能变化。</li></ol><h2 id="_4-清算结果" tabindex="-1">4. 清算结果 <a class="header-anchor" href="#_4-清算结果" aria-label="Permalink to &quot;4. 清算结果&quot;">​</a></h2><p>成功后：持仓减少或清零，保证金与盈亏按清算规则落定，必要时涉及风险准备金等（细节另文）。用户应能凭业务编号追溯强平明细，避免「只看到余额少了」。</p><p>重复清算必须防重：同一持仓不能被多扣占用或多记亏损。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/080502">平仓主流程</a></td><td>用户主动平仓</td></tr><tr><td><a href="/pages/080504">行情推送流程</a></td><td>标记价从哪来、如何推展示</td></tr><tr><td><a href="/pages/0804#risk">核心设计 · 风险</a></td><td>对象与阶段划分</td></tr><tr><td>风险准备金会计、穿仓分摊公式</td><td>不在本文展开</td></tr><tr><td>资金费结算</td><td>另一旁路，不与强平混为一谈</td></tr></tbody></table><p>同组：<a href="/pages/080501">开仓主流程</a> · <a href="/pages/080502">平仓主流程</a> · <a href="/pages/080504">行情推送流程</a> · <a href="/pages/0801">业务概述</a></p>',8))])}const u=r(i,[["render",d]]);export{f as __pageData,u as default};
